    92	    /// Get all properties from a D-Bus interface
    93	    async fn get_all_properties(&self, proxy: &Proxy<'_>) -> Result<HashMap<String, Value>> {
    94	        // Use org.freedesktop.DBus.Properties.GetAll
    95	        let props_proxy = Proxy::new(
    96	            proxy.connection(),
    97	            proxy.destination(),
    98	            proxy.path(),
    99	            "org.freedesktop.DBus.Properties",
   100	        )
   101	        .await?;
   102	
   103	        let all_props: HashMap<String, zbus::zvariant::OwnedValue> = props_proxy
   104	            .call("GetAll", &(proxy.interface(),))
   105	            .await
   106	            .context("Failed to get all properties")?;
   107	
   108	        // Convert to simd_json::OwnedValue HashMap
   109	        let mut result = HashMap::new();
   110	        for (key, _value) in all_props {
   111	            // Simplified conversion - would need proper zvariant to serde_json conversion
   112	            result.insert(key, Value::null());
   113	        }
   114	
   115	        Ok(result)
   116	    }
