   119	    async fn call_method_no_args(
   120	        &self,
   121	        proxy: &Proxy<'_>,
   122	        method: &str,
   123	    ) -> Result<zbus::zvariant::OwnedValue> {
   124	        proxy
   125	            .call(method, &())
